package tv.vela.launcher;

import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.lang.reflect.*;import java.util.*;

/** Owned emulator only: simulated physical inputs, real Android views, remote events and installed app icons. */
public final class LiteIntegrationTest extends Instrumentation {
    private LiteHomeActivity activity;private String phase="start";
    static final class Source implements TvInputs.Source {
        final Context context;Runnable changed;final List<TvInputs.Raw> raw=new ArrayList<>();
        Source(Context c){context=c;raw.add(new TvInputs.Raw("p1",null,"HDMI 1","",TvInputs.CONNECTED));raw.add(new TvInputs.Raw("box","p1","MECOOL KM2 Plus","",TvInputs.CONNECTED));raw.add(new TvInputs.Raw("p2",null,"HDMI 2","",TvInputs.CONNECTED));raw.add(new TvInputs.Raw("ps5","p2","PS5","",TvInputs.CONNECTED));raw.add(new TvInputs.Raw("p3",null,"HDMI 3","",TvInputs.DISCONNECTED));}
        public List<TvInputs.Entry> read(){return TvInputs.resolve(context,raw);}public void start(Runnable listener){changed=listener;}public void stop(){changed=null;}
    }
    public static final class Home extends LiteHomeActivity {protected boolean allowAutomaticChecks(){return false;}
        Source source;boolean noInputs,noTuner;
        protected TvInputs.Source createInputsSource(){source=new Source(this);return source;}
        protected LiteAntennaData createAntennaData(){return new LiteAntennaData(this){boolean permitted(){return false;}};}
        protected LiteCatalog.Tuner readTuner(){return noTuner?null:new LiteCatalog.Tuner("Antena · prueba",new Intent(Intent.ACTION_VIEW,android.media.tv.TvContract.Channels.CONTENT_URI));}
        protected List<LiteCatalog.App> readApps(){List<LiteCatalog.App> apps=new ArrayList<>(super.readApps());if(!apps.isEmpty()){LiteCatalog.App seed=apps.get(0);while(apps.size()<25){int n=apps.size();apps.add(new LiteCatalog.App("fixture"+n,"Aplicación de prueba "+n,seed.component));}}return apps;}
    }
    private Home created;
    public Activity newActivity(ClassLoader loader,String name,Intent intent)throws InstantiationException,IllegalAccessException,ClassNotFoundException{if(name.equals(LiteHomeActivity.class.getName())){created=new Home();return created;}return super.newActivity(loader,name,intent);}
    Object field(Object o,String name)throws Exception{for(Class<?> c=o.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(o);}catch(NoSuchFieldException ignored){}throw new NoSuchFieldException(name);}
    void check(boolean ok,String reason){if(!ok)throw new AssertionError(reason);}
    void ui(Runnable action){runOnMainSync(action);waitForIdleSync();}
    void key(int code){sendKeyDownUpSync(code);waitForIdleSync();}
    void click(View view){ui(view::requestFocus);key(KeyEvent.KEYCODE_DPAD_CENTER);}
    View text(View view,String value){if(view instanceof TextView&&((TextView)view).getText().toString().equals(value))return view;if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++){View found=text(((ViewGroup)view).getChildAt(n),value);if(found!=null)return found;}return null;}
    void shot(String name)throws Exception{Thread.sleep(400);Bitmap bitmap=getUiAutomation().takeScreenshot();check(bitmap!=null&&bitmap.getWidth()==3840&&bitmap.getHeight()==2160,"Expected 4K native capture");try(OutputStream out=new FileOutputStream(new File(getTargetContext().getExternalFilesDir(null),name+".png"))){bitmap.compress(Bitmap.CompressFormat.PNG,100,out);}finally{bitmap.recycle();}}
    List<View> tiles()throws Exception{return (List<View>)field(activity,"tiles");}
    void waitApps()throws Exception{for(int i=0;i<100;i++){waitForIdleSync();if(!tiles().isEmpty())return;Thread.sleep(50);}throw new AssertionError("Apps did not load");}
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle result=new Bundle();ActivityMonitor monitor=null;try{
        Context c=getTargetContext();check(Build.MODEL.contains("sdk")||Build.FINGERPRINT.contains("generic"),"Owned emulator required");check(c.getPackageName().equals("tv.vela.launcher.lite"),"Full Vela must not be altered");TvInputs.prefs(c).edit().clear().commit();c.getSharedPreferences("lite_home",0).edit().clear().commit();
        activity=(LiteHomeActivity)startActivitySync(new Intent(c,LiteHomeActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));View[] nav=(View[])field(activity,"navigation");check(tiles().size()==3,"Physical and CEC inputs were not grouped");check(created.source.read().get(0).title.equals("MECOOL"),"Explicit MECOOL brand not identified");check(created.source.read().get(2).title.equals("HDMI 3"),"Disconnected port was named as a device");shot("lite-01-hdmi");
        phase="remote-and-launch";ui(tiles().get(0)::requestFocus);key(KeyEvent.KEYCODE_DPAD_RIGHT);check(tiles().get(1).hasFocus(),"Right did not move to next port");key(KeyEvent.KEYCODE_DPAD_LEFT);key(KeyEvent.KEYCODE_DPAD_LEFT);check(nav[0].hasFocus(),"Left edge did not return to navigation");key(KeyEvent.KEYCODE_DPAD_RIGHT);check(tiles().get(0).hasFocus(),"Right did not enter input tiles");IntentFilter filter=new IntentFilter(Intent.ACTION_VIEW);filter.addDataScheme("content");monitor=addMonitor(filter,new ActivityResult(Activity.RESULT_CANCELED,null),true);click(tiles().get(0));check(monitor.getHits()==1,"HDMI did not request native passthrough playback");
        phase="antenna";click(nav[1]);check(created.source.changed==null&&field(activity,"worker")==null,"Hidden inputs or TV started a worker");View open=text((View)field(activity,"content"),"Abrir televisión");check(open!=null,"Antenna action missing");shot("lite-02-antena");click(open);check(monitor.getHits()==2,"Antenna did not open the channels intent");removeMonitor(monitor);monitor=null;
        phase="apps-and-pages";click(nav[2]);waitApps();check(tiles().size()==12&&((List<?>)field(activity,"appImages")).size()==12,"Apps not bounded to twelve tiles");Thread.sleep(900);waitForIdleSync();shot("lite-03-aplicaciones");ViewGroup pager=(ViewGroup)field(activity,"pager");check(pager.getChildCount()==3,"Apps pager missing");click(pager.getChildAt(2));check((Integer)field(activity,"appPage")==1&&tiles().size()==12,"Apps page did not advance");Rect pagerRect=new Rect();pager.getGlobalVisibleRect(pagerRect);for(View tile:tiles()){Rect tileRect=new Rect();tile.getGlobalVisibleRect(tileRect);check(!Rect.intersects(pagerRect,tileRect),"Pager overlaps an application tile");}
        phase="lifecycle";click(nav[0]);check(field(activity,"worker")==null&&((List<?>)field(activity,"appImages")).isEmpty(),"App worker/icons retained after leaving drawer");check(((android.util.LruCache<?,?>)field(activity,"appIcons")).size()==0,"App bitmap cache retained after leaving drawer");
        phase="manual-identity-and-hotplug";ui(tiles().get(2)::requestFocus);sendKeySync(new KeyEvent(0,0,KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_CENTER,0));Thread.sleep(ViewConfiguration.getLongPressTimeout()+200);sendKeySync(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_CENTER));waitForIdleSync();check((Integer)field(activity,"section")==4,"Long OK not consumed into integrated profile selection");View profile=text((View)field(activity,"content"),"MECOOL");check(profile!=null,"MECOOL manual profile missing");click(profile);check(created.source.read().get(2).title.equals("HDMI 3"),"Assignment invented an active connection");ui(()->{created.source.raw.set(4,new TvInputs.Raw("p3",null,"HDMI 3","",TvInputs.CONNECTED));created.source.changed.run();});Thread.sleep(250);waitForIdleSync();check(created.source.read().get(2).title.equals("MECOOL"),"Active manually assigned port did not update");check(activity.getCurrentFocus().getContentDescription().toString().contains("HDMI 3"),"Hotplug lost selected port");
        phase="unavailable-hardware";created.noTuner=true;click(nav[1]);check(text((View)field(activity,"content"),"Permitir acceso a la guía")!=null,"TV permission fallback missing");ui(()->created.source.raw.clear());click(nav[0]);check(text((View)field(activity,"content"),"La TV no comparte entradas HDMI")!=null,"No-input explanation missing");
        phase="pause-release";DeviceIcons images=(DeviceIcons)field(activity,"devices");ui(()->callActivityOnPause(activity));check(created.source.changed==null&&field(activity,"worker")==null&&((ViewGroup)field(activity,"content")).getChildCount()==0&&images.closed,"Activity pause retained input listener or images");ui(()->callActivityOnResume(activity));
        result.putString("result","PASS isolated Lite package: native 4K HDMI/antenna/apps captures, MECOOL/CEC grouping, real remote navigation, HDMI/tuner intents intercepted, twelve-app pages, no pager overlap, manual identity never invents a signal, hotplug focus, no-hardware fallbacks, listener/worker/cache/view release on section change and pause. Hardware metadata simulated; no physical Xiaomi or antenna signal tested.");
    }catch(Throwable error){result.putString("phase",phase);result.putString("error",android.util.Log.getStackTraceString(error));}finally{if(monitor!=null)removeMonitor(monitor);if(activity!=null)ui(activity::finish);}finish(result.containsKey("error")?1:-1,result);}
}
